class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Iterate through all possible starting positions 'i' for the first subarray.
        # The first subarray starts at 'i' and ends at 'i + k - 1'.
        # The second subarray starts at 'i + k' and ends at 'i + 2k - 1'.
        # We need to ensure the second subarray is within bounds, so i + 2k - 1 < n.
        # Thus, i goes from 0 to n - 2k.

        for i in range(n - 2 * k + 1):
            # Check if the first subarray nums[i : i + k] is strictly increasing
            first_is_increasing = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    first_is_increasing = False
                    break

            if not first_is_increasing:
                continue

            # Check if the second subarray nums[i + k : i + 2 * k] is strictly increasing
            second_is_increasing = True
            for j in range(i + k, i + 2 * k - 1):
                if nums[j] >= nums[j + 1]:
                    second_is_increasing = False
                    break

            if first_is_increasing and second_is_increasing:
                return True

        return False

class Solution:
    def possibleStringCount(self, word: str) -> int:
        # Count the frequency of each character in the word
        char_count = {}
        for char in word:
            char_count[char] = char_count.get(char, 0) + 1

        # Calculate the number of possible original strings
        # For each character that appears more than once, we can remove one instance
        # to get a valid original string.
        # If a character appears k times, we can remove it k-1 times to get k different original strings.
        # Plus the original string itself (when no key was pressed).

        result = 1  # Always include the original string itself
        for char, count in char_count.items():
            if count > 1:
                result += (count - 1)

        return result

class Solution:
    def canAliceWin(self, n: int) -> bool:
        if n < 10:
            return False
        n -= 10
        req = 9
        while True:
            if req % 2 == 1:
                if n < req:
                    return True
                n -= req
            else:
                if n < req:
                    return False
                n -= req
            req -= 1
